package br.com.mateus.biblioteca;
import java.time.*; import java.util.*;
public final class Library { public record Book(String id,String title){} public record Loan(String bookId,String userId,LocalDate due,LocalDate returned){ public boolean overdue(LocalDate today){return returned==null&&today.isAfter(due);} public int fine(LocalDate today){return Math.max(0,(int)java.time.temporal.ChronoUnit.DAYS.between(due,today))*2;} } private final Map<String,Book> books=new HashMap<>(); private final Map<String,Loan> loans=new HashMap<>(); public void add(Book b){books.put(b.id(),b);} public Loan borrow(String book,String user,LocalDate today,int days){if(!books.containsKey(book))throw new IllegalArgumentException("livro inexistente"); if(loans.values().stream().anyMatch(l->l.bookId().equals(book)&&l.returned()==null))throw new IllegalStateException("livro indisponível"); Loan l=new Loan(book,user,today.plusDays(days),null); loans.put(book+":"+user,l); return l;} public Loan reserve(String book,String user,LocalDate today){return borrow(book,user,today,7);} public Loan giveBack(String book,String user){String k=book+":"+user; Loan l=loans.get(k); if(l==null)throw new IllegalArgumentException("empréstimo inexistente"); Loan done=new Loan(l.bookId(),l.userId(),l.due(),LocalDate.now()); loans.put(k,done); return done;} public int fine(String book,String user,LocalDate today){Loan l=loans.get(book+":"+user); return l==null?0:l.fine(today);} }
